const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Spaces before ? ! ; : and a final full stop do not count, so whole sentences can be checked.
const norm=s=>s.replace(/[  ]/g,' ').trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s*([?!;:])/g,'$1').replace(/[.!?]+$/,'').replace(/\s+/g,' ').trim();
const searchNorm=s=>norm(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const strip=s=>String(s).replace(/<[^>]*>/g,' ');
