const OG=typeof oralGuide!=='undefined'?oralGuide:null,OT=typeof oralTopics!=='undefined'?oralTopics:[],WG=typeof writingGuide!=='undefined'?writingGuide:null,XQ=typeof extraQuestions!=='undefined'?extraQuestions:{},RC=typeof recits!=='undefined'&&Array.isArray(recits)?recits:[],LX=typeof lectures!=='undefined'&&Array.isArray(lectures)?lectures:[];
const groups=[['01','Les temps',['present','pc','imparfait','choisir','pqp','subjonctif','conditionnel','futur']],['02','Les pronoms',['pronoms','yen','place','doubles','relatifs','relief','demonstratifs']],['03','Les mots utiles',['reperes','expressions','opinions','reproches','adverbes']]];
