$('#search-toggle').onclick=openSearch;$('#search-close').onclick=()=>closeSearch(true);
function cards(lesson='all'){
 const toc=(href,title,sub,n)=>`<li><a href="${href}"><span class="toc-text"><span class="toc-title">${title}</span><small>${sub}</small></span><span class="toc-leader" aria-hidden="true"></span><span class="toc-n" aria-hidden="true">${n}</span></a></li>`;
 const examChapter=lesson==='all'?`<section class="notebook-chapter exam-chapter"><span class="chapter-number" aria-hidden="true">04</span><div class="chapter-content"><h2>Préparer l’examen</h2><ul>${examPages.map(([id,t,sub,ic])=>toc('#'+id,t,sub,ic)).join('')}</ul></div></section>`:'';
 return groups.map(([number,title,ids])=>{const list=ids.map(id=>modules.find(m=>m.id===id)).filter(m=>lesson==='all'||(lesson==='supplement'?m.lessons.length===0:m.lessons.includes(+lesson)));return list.length?`<section class="notebook-chapter"><span class="chapter-number" aria-hidden="true">${number}</span><div class="chapter-content"><h2>${title}</h2><ul>${list.map(m=>toc('#'+m.id,m.title,m.subtitle,m.n)).join('')}</ul></div></section>`:''}).join('')+examChapter;
}
function home(){main.innerHTML=`<div class="notebook"><header class="notebook-header"><p class="eyebrow">B1− · cours 1 à 16</p><h1>Mon carnet de français</h1><p class="lede">Les temps, les pronoms et les mots utiles, fiche par fiche. Avec un rappel complémentaire sur le futur et de quoi préparer l’examen.</p><div class="notebook-meta"><span>Afficher :</span><label class="filter-label"><span class="sr-only">Filtrer par cours</span><select id="lesson-filter" aria-label="Filtrer par cours"><option value="all">Tout le carnet</option><option value="supplement">Compléments</option>${Array.from({length:16},(_,i)=>`<option value="${i+1}">Cours ${i+1}</option>`).join('')}</select></label></div></header><div id="cards">${cards()}</div><a class="notebook-reference" href="#verbes"><svg viewBox="0 0 28 24" aria-hidden="true"><path d="M14 5C10 2 5 2 2 3v17c4-1 8-1 12 2 4-3 8-3 12-2V3c-3-1-8-1-12 2Zm0 0v17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg><span>Répertoire des verbes<small>27 verbes, 7 formes et les participes passés</small></span><span aria-hidden="true">›</span></a><a class="notebook-exam" href="#test">Préparer le test final →</a></div>`;$('#lesson-filter').onchange=e=>$('#cards').innerHTML=cards(e.target.value)}
// i indexes the question list passed to bindQuestions; num is the number shown.
function questionHTML(q,i,num=i+1){const [before,after]=q[0].includes('___')?q[0].split('___'):[q[0],null];const n=`<span class="n">${num}.</span>`;
 if(q[3])return `<div class="question"><p>${n}${esc(before)}${after!==null?'<span class="blank" aria-hidden="true">&nbsp;?&nbsp;</span>'+esc(after):''}</p><div class="choices" role="group" aria-label="Choix ${i+1}" data-index="${i}">${q[3].map(o=>`<button type="button">${esc(o)}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p></div>`;
 const input=`<input class="blank${after===null?' wide':''}" aria-label="Réponse ${i+1}" autocomplete="off" spellcheck="false" autocapitalize="none" size="${Math.max(6,q[1].split('|')[0].length+2)}">`;
 return `<form class="question" data-index="${i}"><p>${n}${esc(before)}${after!==null?input+esc(after):''}</p>${after===null?input:''}<div class="answer-row"><button type="submit">Vérifier</button><button type="button" class="reveal">Voir la réponse</button></div><p class="feedback" aria-live="polite"></p></form>`}
// Récits: stories whose items read in order as one narrative; only on the fiche choisir.
const recitHTML=(r,start)=>`<article class="recit" aria-labelledby="recit-${esc(r.id)}"><h3 id="recit-${esc(r.id)}">${r.title}</h3>${r.intro?`<p class="recit-intro">${r.intro}</p>`:''}${r.items.map((q,k)=>questionHTML(q,start+k,k+1)).join('')}</article>`;
function recitsSection(start){let k=start;return `<section class="practice recits" id="recits" aria-labelledby="recits-title"><h2 id="recits-title">Récits à compléter</h2><p>Chaque récit se lit d’un bout à l’autre : conjugue le verbe entre parenthèses au passé composé, à l’imparfait ou au plus-que-parfait selon son rôle dans l’histoire. Les accents comptent, pas les majuscules.</p>${RC.map(r=>{const h=recitHTML(r,k);k+=r.items.length;return h}).join('')}<p class="practice-note">Tu peux aussi les faire dans le <a href="#quiz">quiz</a>, mode « Récits au passé ».</p></section>`}
function modulePage(m){const xq=XQ[m.id]||[],rc=m.id==='choisir'?RC:[],all=m.q.concat(xq,rc.flatMap(r=>r.items));main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><p class="eyebrow">Fiche ${m.n} · ${m.tag.toLowerCase()}</p><h1>${m.title}</h1><p>${m.intro}</p><div class="chips">${m.lessons.map(l=>`<span class="chip">cours ${l}</span>`).join('')}</div></header><div class="lesson-layout"><article class="lesson-body">${m.sections.map((s,i)=>`<section class="content-section" id="section-${i}"><h2>${s[0]}</h2>${s[1]}</section>`).join('')}<details lang="en"><summary>English clarification</summary><p>${m.en}</p></details>${all.length?`<section class="practice"><h2>À toi !</h2><p>Les accents comptent, pas les majuscules.</p>${m.q.map((q,i)=>questionHTML(q,i)).join('')}${xq.length?`<h3 class="practice-sub" id="transforme">Transforme</h3><p class="practice-note">Réécris la phrase entière en suivant la consigne ; « Voir la réponse » montre une solution possible.</p>${xq.map((q,j)=>questionHTML(q,m.q.length+j,j+1)).join('')}`:''}</section>`:''}${rc.length?recitsSection(m.q.length+xq.length):''}<p class="source"><b>Sources et périmètre.</b> ${m.source}</p><div class="bottom-band"><a href="#${modules[(modules.indexOf(m)+1)%modules.length].id}">${modules[(modules.indexOf(m)+1)%modules.length].title} →</a><button class="btn" onclick="window.print()">Imprimer cette fiche</button></div></article><aside class="lesson-toc"><p class="eyebrow">Dans cette fiche</p>${m.sections.map((s,i)=>`<a href="#${m.id}" data-scroll="section-${i}">${s[0]}</a>`).join('')}${xq.length?`<a href="#${m.id}" data-scroll="transforme">Transforme</a>`:''}${rc.length?`<a href="#${m.id}/recits" data-scroll="recits">Récits à compléter</a>`:''}<a href="#verbes">Répertoire des verbes ↗</a></aside></div>`;
main.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll).scrollIntoView({behavior:'smooth'})});
bindQuestions(main,all)}
// Shared checking for fiches and the quiz. onResult(index, correct) runs on every check; a revealed answer counts as not found.
function bindQuestions(root,list,onResult=()=>{}){
 const say=(el,cls,text)=>{el.className='feedback'+(cls?' '+cls:'');el.textContent=text};
 root.querySelectorAll('form.question').forEach(f=>{const i=+f.dataset.index,q=list[i],input=f.querySelector('input'),feedback=f.querySelector('.feedback');f.onsubmit=e=>{e.preventDefault();if(!input.value.trim())return say(feedback,'','Écris une réponse avant de vérifier.');const ok=q[1].split('|').some(a=>norm(a)===norm(input.value));say(feedback,ok?'success':'review',ok?'✓ Oui. '+q[2]:'Pas encore. Relis la règle, puis réessaie.');onResult(i,ok)};f.querySelector('.reveal').onclick=()=>{const a=q[1].split('|')[0];say(feedback,'','Réponse : '+a+(/[.!?…]$/.test(a)?' ':'. ')+q[2]);onResult(i,false)}});
 root.querySelectorAll('.choices').forEach(g=>{const i=+g.dataset.index,q=list[i],feedback=g.nextElementSibling;g.querySelectorAll('button').forEach(b=>b.onclick=()=>{const ok=b.textContent===q[1];b.classList.add(ok?'right':'wrong');say(feedback,ok?'success':'review',ok?'✓ Oui. '+q[2]:'Pas celle-ci. Essaie encore.');onResult(i,ok)})})}
function conjugated(v,tense){const p=v[1].split(','),reflexive=v[0]==='s’appeler';if(tense==='present')return p;if(tense==='subjonctif')return subjunctive(v);if(tense==='conditionnel')return conditional(v);if(tense==='futur')return conditional(v,true);if(tense==='imparfait'){if(v[0]==='être')return ['étais','étais','était','étions','étiez','étaient'];const stem=reflexive?'appel':p[3].slice(0,-3);return ['ais','ais','ait','ions','iez','aient'].map((end,i)=>{let s=stem;if(v[0]==='manger'&&(i===3||i===4))s='mang';let word=s+end;if(reflexive){const r=['m’','t’','s’','nous ','vous ','s’'][i];word=r+word}return word})}const etre=v[3]==='être';let aux=tense==='pc'?(etre?['suis','es','est','sommes','êtes','sont']:['ai','as','a','avons','avez','ont']):(etre?['étais','étais','était','étions','étiez','étaient']:['avais','avais','avait','avions','aviez','avaient']);return aux.map((a,i)=>{let pp=v[2]+(etre?(i===3||i===4||i===5?'s':''):'');if(reflexive){let r=['me ','te ','se ','nous ','vous ','se '][i];if(/^[aeé]/.test(a))r=['m’','t’','s’','nous ','vous ','s’'][i];a=r+a}return a+' '+pp})}
function verbPage(selected){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><div class="verb-panel"><header class="page-header compact"><div><p class="eyebrow">Répertoire des verbes · 27 verbes, 7 formes</p><h1>Conjugaison</h1></div><div class="verb-tools"><label>Le verbe<select id="verb">${verbs.map((v,i)=>`<option value="${i}">${v[0]}</option>`).join('')}</select></label></div></header><div id="verb-output"></div><section class="content-section"><h2>Les participes passés, à l’oreille</h2><p>Comme dans le rappel du cours 1, les participes sont rangés par le son final. Au féminin, on entend parfois la consonne : <b>prise, mise, écrite, faite</b>.</p><div class="pp-grid">${participleGroups.map(([sound,note,list])=>`<section><h3>-${sound}${note?`<small>${note}</small>`:''}</h3><ul>${list.map(([inf,pp,extra])=>`<li${extra?' class="extra"':''}><span>${inf}</span><b>${pp}</b></li>`).join('')}</ul></section>`).join('')}</div><p class="muted">° Rencontré dans les récits et les devoirs. Falloir et pleuvoir s’emploient avec il : il a fallu, il a plu. L’auxiliaire dépend de la construction : elle est sortie, mais elle a sorti son sac.</p></section><p class="source">Sources : Cours 1 · verbes_frequents_indicatif_present.pdf, p. 1 ; Le passé composé RAPPEL.docx ; Cours 2, 8, 9 et 12 pour les règles de formation ; bases irrégulières du conditionnel complétées comme référence. Le futur simple est un complément de révision, avec les mêmes bases. Les tableaux aux autres temps sont générés à partir de ces règles.</p></div>`;if(selected){const i=verbs.findIndex(v=>v[0]===selected);if(i>=0)$('#verb').value=i}$('#verb').onchange=()=>{history.replaceState(null,'','#verbes/'+encodeURIComponent(verbs[+$('#verb').value][0]));drawVerb()};drawVerb()}
function drawVerb(){const v=verbs[+$('#verb').value],pronouns=['je','tu','il / elle / on','nous','vous','ils / elles'],tenses=[['present','Présent'],['imparfait','Imparfait'],['pc','Passé composé'],['pqp','Plus-que-parfait'],['subjonctif','Subjonctif présent (que…)'],['conditionnel','Conditionnel présent'],['futur','Futur simple']];
 // With être, compound tenses show the agreement in the row itself: allé(e), elle est allée, elles sont allées.
 const rows=t=>{const f=conjugated(v,t),list=f.map((x,i)=>[pronouns[i],x]);if(!['pc','pqp'].includes(t)||v[3]!=='être')return list;const pp=v[2];return [['je',f[0]+'(e)'],['tu',f[1]+'(e)'],['il / on',f[2]],['elle',f[2]+'e'],['nous',f[3].replace(pp+'s',pp+'(e)s')],['vous',f[4].replace(pp+'s',pp+'(e)(s)')],['ils',f[5]],['elles',f[5].replace(pp+'s',pp+'es')]]};
 const block=([t,label])=>`<section class="tense-block"><h3>${label}</h3><ul>${rows(t).map(([pr,f])=>`<li>${pr==='je'&&/^[aeéiou]/.test(f)?`<span>j’</span><b>${f}</b>`:`<span>${pr}</span> <b>${f}</b>`}</li>`).join('')}</ul></section>`;
 $('#verb-output').innerHTML=`<div class="verb-card"><div class="verb-title"><h2>${v[0]}</h2><div class="meta-row"><div><small>Participe passé</small><b>${v[2]}</b></div><div><small>Auxiliaire</small><b>${v[3]||'avoir'}</b></div></div></div><div class="tense-blocks">${tenses.map(block).join('')}</div></div>${v[3]==='être'?'<div class="warning">Avec être, le participe s’accorde avec le sujet : (e) au féminin, s au pluriel. Vous de politesse : vous êtes venu / venue pour une personne.</div>':''}${v[0]==='s’appeler'?'<p class="muted">Au passé, ces formes signifient « se nommer » (il s’est appelé Paul) ou « s’appeler l’un l’autre » (nous nous sommes appelés). Pour présenter son nom, utilise normalement le présent.</p>':''}${v[0]==='être'?'<p class="muted">Être utilise avoir aux temps composés : j’ai été, j’avais été.</p>':''}`}
function exam(){main.innerHTML=`<a class="back" href="#accueil">← Sommaire</a><header class="page-header"><p class="eyebrow">Examen final</p><h1>Préparer le test</h1><p>Ce carnet résume les cours 1 à 16. Il ne prétend pas couvrir tout le programme ni prédire les questions du test final.</p></header><div class="exam-grid"><section><h2>Une séance de 30 min</h2><p><b>1. Quiz (10 min).</b> Fais un <a href="#quiz">quiz mélangé</a> de 20 questions. Note les fiches à revoir affichées à la fin.</p><p><b>2. Une fiche (5 min).</b> Ouvre la première fiche de cette liste. Relis seulement la règle ratée, puis fais son bloc « Transforme ».</p><p><b>3. Un texte (5 min).</b> Lis un <a href="#lire">texte</a> et réponds aux cinq questions.</p><p><b>4. L’oral (10 min).</b> <a href="#oral">Tire un sujet</a>, prépare 7 minutes avec le minuteur, puis parle 3 minutes à voix haute.</p><p><b>Deux fois par semaine :</b> remplace les étapes 2 et 3 par une <a href="#ecrire">rédaction</a> de 120 à 150 mots, puis relis-la avec la liste de contrôle.</p><p class="muted">Avant l’écrit (25 novembre) : chaque jour un <a href="#choisir/recits">récit au passé</a>. Entre l’écrit et l’oral (3 décembre) : seulement l’étape 4, deux sujets par jour.</p><a class="btn primary" href="#quiz">Commencer par le quiz</a></section><section><h2>Les priorités du carnet</h2><ul><li>Former les temps et choisir le bon passé.</li><li>Connaître les verbes fréquents et leurs participes.</li><li>Choisir et placer COD, COI, y et en.</li><li>Distinguer les repères temporels.</li><li>Former le subjonctif et choisir le mode.</li><li>Exprimer une opinion, un conseil et une demande au conditionnel.</li><li>Relier les idées avec qui, que, dont et où ; utiliser la mise en relief et les démonstratifs.</li><li>Former des adverbes et nuancer un avis sur les générations.</li><li>Réutiliser ces structures dans un court récit.</li></ul><p class="muted">Priorités fondées sur les exercices du cours, pas sur une liste officielle des questions d’examen.</p></section><section><h2>Le format confirmé</h2><p><b>Rendez-vous (heure de Genève) :</b> écrit le 25 novembre 2026 à 15:45 (début repris du tableau de progression). Oral le 3 décembre 2026 à 13:45, selon le planning B1 du document d’examen. Vérifie la convocation pour le lieu de l’écrit.</p><p><b>Écrit : 1 h 45, sur 50 points.</b> Sur Microsoft Forms, pendant le dernier cours. L’écoute vient en premier : arrive à l’heure, car les retardataires doivent passer à la session de rattrapage. Puis viennent grammaire, conjugaison, vocabulaire, lecture et rédaction. Prévois ton téléphone pour la double authentification CERN ; un lien séparé est prévu sans compte CERN.</p><p><b>Oral : rendez-vous de 15 min, sur 50 points.</b> 7 min de préparation et 5 à 6 min de monologue et interaction.</p><p><b>Réussite : 60 / 100.</b> Aucun exercice d’écoute n’est intégré à ce carnet.</p></section><section class="exam-links"><h2>S’entraîner</h2><p>L’oral compte pour la moitié de la note : présenter un document, ses points forts et ses points faibles, donner son avis, puis répondre aux questions.</p>${examPages.slice(1).map(([id,t,sub])=>`<a class="notebook-reference" href="#${id}"><span>${t}<small>${sub}</small></span><span aria-hidden="true">›</span></a>`).join('')}<p class="muted">Pour les phrases toutes faites, voir aussi le <a href="#expressions">mémo de phrases</a>.</p></section></div><details><summary>Sources, limites et suivi</summary><p>Fondé sur FrenchB1m_lesson1-16.zip (vérifié le 15 novembre 2026), les fiches fournies des cours 1 à 16 et B1- EXAMEN.docx. Les explications et les exercices sont reformulés ; les compléments de référence sont signalés.</p><p>Le document d’examen donne une note globale d’oral sur 50 et une grille séparée sur 20, sans expliquer leur correspondance. Les thèmes exacts de l’examen ne sont pas confirmés.</p><p>Les points seulement annoncés dans le programme, comme le futur antérieur, ne sont pas inclus. Le futur proche/simple reste un complément identifié séparément. De nouveaux cours pourront enrichir les fiches.</p><p>Les réponses ici sont des essais d’entraînement. Elles ne sont pas sauvegardées et ne mesurent pas la rétention. Le tableau de progression reste le registre des évaluations faites en séance.</p></details><p class="source">Examen : B1- EXAMEN.docx, pp. 1–4. Ce site ne contient ni enregistrement ni exercice d’écoute.</p>`}
const missing='<p class="warning">Le fichier exam-content.js n’est pas chargé : cette page est vide pour l’instant.</p>';
const backHome='<a class="back" href="#accueil">← Sommaire</a>';
const listHTML=(a,tag='ul')=>`<${tag}>${a.map(x=>`<li>${x}</li>`).join('')}</${tag}>`;
const bankHTML=a=>`<div class="bank">${a.map(([cat,list])=>`<section><h3>${cat}</h3>${listHTML(list)}</section>`).join('')}</div>`;
const checklistHTML=a=>`<ul class="checklist">${a.map(([label,a2,a3])=>`<li><label><input type="checkbox"><b>${label}</b>${a3!==undefined?`<span class="pts">${a2} pt${+a2>1?'s':''}</span><span class="tip">${a3}</span>`:`<span class="tip">${a2}</span>`}</label></li>`).join('')}</ul>`;
const stepsHTML=a=>`<ol class="steps">${a.map(([t,h])=>`<li><h3>${t.replace(/^\d+\.\s*/,'')}</h3><div>${h}</div></li>`).join('')}</ol>`;

// Timers: one interval each, all cleared when the route changes.
let timers=[];
function stopTimers(){timers.forEach(t=>clearInterval(t.iv));timers=[]}
const clock=s=>Math.floor(s/60)+':'+String(s%60).padStart(2,'0');
const timerHTML=(id,label,sec)=>`<div class="timer" id="${id}" data-sec="${sec}"><div><p class="timer-label">${label}</p><p class="timer-digits" role="timer" aria-label="${label}">${clock(sec)}</p></div><div class="timer-buttons"><button type="button" class="btn primary" data-act="go">Démarrer</button><button type="button" class="btn" data-act="reset">Remettre à zéro</button></div></div>`;
function bindTimer(el,live){const sec=+el.dataset.sec,digits=el.querySelector('.timer-digits'),go=el.querySelector('[data-act=go]'),label=el.querySelector('.timer-label').textContent,t={left:sec,iv:null};timers.push(t);
 const draw=()=>digits.textContent=clock(t.left),stop=()=>{clearInterval(t.iv);t.iv=null;el.classList.remove('running')};
 go.onclick=()=>{if(t.iv){stop();go.textContent='Reprendre';return}if(!t.left){t.left=sec;el.classList.remove('done')}const end=Date.now()+t.left*1000;el.classList.add('running');go.textContent='Pause';live.textContent='';
  t.iv=setInterval(()=>{t.left=Math.max(0,Math.ceil((end-Date.now())/1000));draw();if(!t.left){stop();el.classList.add('done');go.textContent='Recommencer';live.textContent=label+' : temps écoulé.'}},250)};
 el.querySelector('[data-act=reset]').onclick=()=>{stop();t.left=sec;el.classList.remove('done');go.textContent='Démarrer';draw()}}

function topicHTML(t){const i=OT.indexOf(t);return `<article class="topic-card"><p class="eyebrow">Sujet ${i+1} sur ${OT.length}</p><h3 id="topic-title" tabindex="-1">${t.title}</h3><div class="example topic-doc">${t.document}</div><p class="muted">Réfléchis d’abord : le thème, les points forts, les points faibles, ton avis. Ensuite seulement, ouvre les aides.</p>
<details><summary>Arguments pour et contre</summary><div class="pros-cons"><div><h4 class="pour">Pour</h4>${listHTML(t.pour)}</div><div><h4 class="contre">Contre</h4>${listHTML(t.contre)}</div></div></details>
<details><summary>Vocabulaire utile</summary><ul class="vocab">${t.vocab.map(([fr,en])=>`<li><b>${fr}</b><span lang="en">${en}</span></li>`).join('')}</ul></details>
<details><summary>Une amorce pour commencer</summary><p class="amorce">${t.amorce}</p></details>
<details><summary>Les questions de l’examinateur</summary>${listHTML(t.questions,'ol')}</details></article>`}
function showTopic(t,focus){$('#topic').innerHTML=topicHTML(t);$('#draw-topic').textContent='Tirer un autre sujet';history.replaceState(null,'','#oral/'+encodeURIComponent(t.id));setTitle(strip(t.title)+' · oral');if(focus)$('#topic-title').focus()}
function oral(topicId){const g=OG;main.innerHTML=`${backHome}<header class="page-header"><p class="eyebrow">Examen · oral, 50 points sur 100</p><h1>Préparer l’oral</h1><p>7 minutes de préparation, puis 5 à 6 minutes de monologue et d’échange. Tu présentes un document et son thème, ses points forts et ses points faibles avec des exemples, ton opinion, puis tu réponds aux questions.</p><div class="chips"><span class="chip">7 min de préparation</span><span class="chip">5–6 min devant l’examinateur</span><span class="chip">au moins 3 min de parole</span><a class="chip" href="#oral-practice" data-jump>Aller à l’entraînement ↓</a></div></header>
<div class="lesson-body wide">${g?`<section class="content-section" id="oral-steps"><h2>Le déroulé du monologue</h2>${stepsHTML(g.steps)}</section>`:missing}
<section class="practice" id="oral-practice" aria-labelledby="practice-title"><h2 id="practice-title">S’entraîner</h2><p>Tire un sujet, prépare-toi 7 minutes, puis parle au moins 3 minutes à voix haute.</p>${OT.length?`<button type="button" class="btn primary" id="draw-topic">Tirer un sujet</button>`:''}<div class="timers">${timerHTML('t-prep','Préparation',420)}${timerHTML('t-talk','Prise de parole',180)}</div><div id="topic"></div><p class="sr-only" aria-live="assertive" id="timer-live"></p></section>
${g?`<section class="content-section"><h2>Les connecteurs</h2><p>Choisis-en deux ou trois par étape et entraîne-toi à les dire sans les lire.</p>${bankHTML(g.connectors)}</section>
<section class="content-section"><h2>La grille, pour se vérifier</h2><p>Après un essai, coche ce que tu as vraiment fait. Rien n’est enregistré.</p>${checklistHTML(g.grid)}<p class="muted">Total de la grille : ${g.grid.reduce((s,r)=>s+(+r[1]||0),0)} points. La note d’oral est sur 50 : en supposant une conversion proportionnelle, 1 point de grille vaut 2,5 points. Avantages et inconvénients (4) pèsent donc environ 10 points sur 50 ; vocabulaire et grammaire (3 chacun), 7,5 points chacun.</p></section>
<section class="content-section"><h2>Pendant les 7 minutes</h2>${listHTML(g.prep)}</section>`:''}
${OT.length?`<section class="content-section"><h2>Tous les sujets</h2><ul class="topic-list">${OT.map(t=>`<li><a href="#oral/${encodeURIComponent(t.id)}">${t.title}</a></li>`).join('')}</ul></section>`:''}<p class="source">Format : B1- EXAMEN.docx. Étapes, connecteurs, sujets et conseils rédigés pour ce carnet à partir des thèmes du cours ; ce ne sont pas les sujets de l’examen.</p></div>`;
 const live=$('#timer-live');main.querySelectorAll('.timer').forEach(el=>bindTimer(el,live));
 main.querySelector('[data-jump]').onclick=e=>{e.preventDefault();$('#oral-practice').scrollIntoView()};
 if(OT.length){$('#draw-topic').onclick=()=>{const cur=OT.find(t=>'#oral/'+encodeURIComponent(t.id)===location.hash),pool=OT.length>1?OT.filter(t=>t!==cur):OT;showTopic(pool[Math.floor(Math.random()*pool.length)],true)};
  const t=topicId&&OT.find(x=>x.id===topicId);if(t)showTopic(t);else if(topicId)history.replaceState(null,'','#oral')}}

function ecrire(){const g=WG;if(!g){main.innerHTML=backHome+'<header class="page-header"><h1>Préparer la rédaction</h1></header>'+missing;return}
 main.innerHTML=`${backHome}<header class="page-header"><p class="eyebrow">Examen · rédaction</p><h1>Préparer la rédaction</h1><p>Deux types de textes à savoir construire : une consigne, un plan, des formules et un modèle à lire après avoir essayé.</p><div class="chips"><span class="chip">120–150 mots</span><span class="chip">introduction · développement · conclusion</span></div></header><div class="lesson-body wide">
<div class="tabs" role="tablist" aria-label="Type de texte">${g.types.map((t,i)=>`<button type="button" role="tab" id="tab-${t.id}" aria-controls="panel-${t.id}" aria-selected="${!i}" tabindex="${i?-1:0}">${t.title}</button>`).join('')}</div>
${g.types.map((t,i)=>`<section class="tab-panel" role="tabpanel" id="panel-${t.id}" aria-labelledby="tab-${t.id}"${i?' hidden':''}><h2 class="print-only">${t.title}</h2><h3>La consigne</h3><div class="example">${t.consigne}</div><h3>Le plan</h3>${stepsHTML(t.plan)}<h3>Formules utiles</h3>${bankHTML(t.formules)}<details class="model"><summary>Lire le texte modèle (après avoir essayé)</summary><div class="model-text">${t.modele}</div></details></section>`).join('')}
<section class="content-section"><h2>Avant de rendre : relis-toi</h2><p>Coche au fur et à mesure. Rien n’est enregistré.</p>${checklistHTML(g.checklist)}</section>
<section class="practice" aria-labelledby="write-title"><h2 id="write-title">S’entraîner</h2><p>Rien n’est enregistré ni corrigé : copie ton texte ailleurs si tu veux le garder.</p>${g.sujets.length?'<button type="button" class="btn primary" id="draw-sujet">Tirer un sujet</button>':''}<div id="sujet" aria-live="polite"></div><label class="write-label" for="draft">Ton texte</label><textarea id="draft" rows="9" spellcheck="true" lang="fr" aria-describedby="wc"></textarea><div class="wc" id="wc"><span class="wc-bar" aria-hidden="true"><span></span></span><span id="wc-text">0 mot · objectif 120–150</span></div><p class="sr-only" aria-live="polite" id="wc-live"></p></section><p class="source">Plans, formules, modèles et sujets rédigés pour ce carnet ; la longueur de 120–150 mots vient des devoirs 6 et 8, pas d’une consigne confirmée de l’examen.</p></div>`;
 const tabs=[...main.querySelectorAll('[role=tab]')],select=tab=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;$('#'+b.getAttribute('aria-controls')).hidden=!on})};
 tabs.forEach((b,i)=>{b.onclick=()=>select(b);b.onkeydown=e=>{const d={ArrowRight:1,ArrowLeft:-1}[e.key];if(d){const n=tabs[(i+d+tabs.length)%tabs.length];select(n);n.focus()}}});
 if(g.sujets.length){let last=-1;$('#draw-sujet').onclick=()=>{let k;do k=Math.floor(Math.random()*g.sujets.length);while(g.sujets.length>1&&k===last);last=k;const s=g.sujets[k],type=g.types.find(t=>t.id===s.type);$('#sujet').innerHTML=`<div class="example sujet">${type?`<p class="eyebrow">${type.title}</p>`:''}${s.consigne}</div>`;$('#draw-sujet').textContent='Tirer un autre sujet';if(type)select($('#tab-'+type.id))}}
 let state='';$('#draft').oninput=e=>{const n=wordCount(e.target.value),s=n<120?'':n<=150?'ok':'over';$('#wc-text').textContent=`${n} mot${n>1?'s':''} · objectif 120–150`;$('#wc').className='wc '+s;$('#wc .wc-bar span').style.width=Math.min(100,n/150*100)+'%';if(s!==state){state=s;$('#wc-live').textContent=s==='ok'?'Entre 120 et 150 mots.':s==='over'?'Plus de 150 mots.':''}}}

// Reading: six short texts with multiple-choice questions; one answer per question, nothing saved.
const typeLabel=t=>({article:'Article',courriel:'Courriel',annonce:'Annonce','témoignage':'Témoignage'}[t]||t);
const readingAdvice='<p class="reading-advice"><b>À l’examen :</b> lis d’abord les questions, puis le texte. « On ne sait pas » veut dire que le texte ne le dit pas.</p>';
const drawText=cur=>{const pool=LX.length>1?LX.filter(x=>x!==cur):LX;location.hash='#lire/'+encodeURIComponent(pool[Math.floor(Math.random()*pool.length)].id)};
function lire(id){if(!LX.length){main.innerHTML=backHome+'<header class="page-header"><h1>Préparer la lecture</h1></header>'+missing;return}
 const t=id&&LX.find(x=>x.id===id);if(t)return readingText(t);if(id)history.replaceState(null,'','#lire');
 main.innerHTML=`${backHome}<header class="page-header"><p class="eyebrow">Examen · lecture</p><h1>Préparer la lecture</h1><p>À l’écrit, la lecture propose trois textes courts suivis de questions. Ici, ${LX.length} textes sur les thèmes du cours, avec leurs questions et un peu de vocabulaire.</p><div class="chips"><span class="chip">${LX.length} textes</span><span class="chip">questions à choix</span><span class="chip">vrai · faux · on ne sait pas</span></div></header><div class="lesson-body wide">${readingAdvice}<button type="button" class="btn primary" id="draw-text">Tirer un texte</button><ul class="reading-list">${LX.map((x,i)=>`<li><a href="#lire/${encodeURIComponent(x.id)}"><span class="reading-n" aria-hidden="true">${i+1}</span><span class="toc-text"><span class="toc-title">${x.title}</span><small>${wordCount(strip(x.texte))} mots · ${x.questions.length} questions</small></span><span class="chip">${typeLabel(x.type)}</span></a></li>`).join('')}</ul><p class="source">Textes et questions rédigés pour ce carnet sur les thèmes du cours ; ce ne sont pas les textes de l’examen.</p></div>`;
 $('#draw-text').onclick=()=>drawText(null)}
function readingText(t){const k=LX.indexOf(t),next=LX[(k+1)%LX.length],n=t.questions.length,res=[];setTitle(strip(t.title)+' · lecture');
 main.innerHTML=`<a class="back" href="#lire">← Tous les textes</a><p class="eyebrow">Préparer la lecture · texte ${k+1} sur ${LX.length}</p>${readingAdvice}<div class="reading-layout"><div class="reading-col"><article class="reading-doc" id="reading-text" tabindex="-1" aria-labelledby="doc-title"><p class="doc-kind">${typeLabel(t.type)}<span>${wordCount(strip(t.texte))} mots</span></p><h1 id="doc-title">${t.title}</h1><div class="doc-body">${t.texte}</div></article>${t.lexique.length?`<details class="reading-lexique"><summary>Aide : vocabulaire</summary><ul class="vocab">${t.lexique.map(([fr,en])=>`<li><b>${fr}</b><span lang="en">${en}</span></li>`).join('')}</ul></details>`:''}</div><section class="practice reading-questions" aria-labelledby="rq-title"><h2 id="rq-title">Questions</h2><p>Une réponse par question : elle compte pour le score, puis l’explication s’affiche.</p><a class="reread" href="#reading-text">Revoir le texte ↑</a>${t.questions.map((q,i)=>questionHTML(q,i)).join('')}<div id="reading-score" aria-live="polite"></div></section></div><p class="source">Texte, vocabulaire et questions rédigés pour ce carnet ; ce n’est pas un texte de l’examen.</p>`;
 main.querySelector('.reread').onclick=e=>{e.preventDefault();const d=$('#reading-text');d.scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'start'});d.focus({preventScroll:true})};
 // First answer counts: lock the choices, show the right one and the explanation.
 bindQuestions(main.querySelector('.reading-questions'),t.questions,(i,ok)=>{if(res[i]!==undefined)return;res[i]=ok;const q=t.questions[i],g=main.querySelector(`.choices[data-index="${i}"]`);g.classList.add('answered');g.querySelectorAll('button').forEach(b=>{b.disabled=true;if(b.textContent===q[1])b.classList.add('right')});if(!ok){const fb=g.nextElementSibling;fb.className='feedback';fb.innerHTML=`<span class="review">Non.</span> Réponse : <b>${esc(q[1])}</b>. ${esc(q[2])}`}
  if(res.filter(x=>x!==undefined).length<n)return;const sc=res.filter(Boolean).length;
  $('#reading-score').innerHTML=`<div class="reading-score"><p class="score-line">Score : <b>${sc} / ${n}</b></p><p>${sc===n?'Tout juste. Bravo !':sc>=n*.6?'Bien. Relis les explications de tes erreurs dans le texte.':'Relis le texte avec l’aide du vocabulaire, puis passe au suivant.'}</p><div class="answer-row"><a class="btn primary" href="#lire/${encodeURIComponent(next.id)}">Texte suivant →</a><button type="button" class="btn" id="draw-other">Tirer un autre texte</button></div></div>`;
  $('#draw-other').onclick=()=>drawText(t)})}

// Mixed quiz: kept in memory only, so coming back from a fiche resumes it.
let quizState=null;
const quizFilters=[['all','Toutes les fiches'],...groups.map(([n,t])=>['g'+n,t]),['l1-8','Cours 1 à 8'],['l9-16','Cours 9 à 16'],...(RC.length?[['recits','Récits au passé']]:[])];
// Récits mode: stories in random order, items of each story kept in order. Story items never enter the other draws.
function recitPool(){const m=modules.find(x=>x.id==='choisir');return shuffle(RC).flatMap((r,ri)=>r.items.map((q,k)=>({q,m,r,ri,k})))}
const quizIntro=f=>f==='recits'?`Les ${RC.length} récits dans un ordre au hasard, phrase par phrase (${RC.reduce((s,r)=>s+r.items.length,0)} questions). Les accents comptent, pas les majuscules. Rien n’est enregistré.`:'20 questions tirées au hasard dans les fiches, une à la fois. Les accents comptent, pas les majuscules. Rien n’est enregistré.';
function quizPool(f){const ids=f[0]==='g'?groups.find(g=>g[0]===f.slice(1))[2]:null,[a,b]=f[0]==='l'?f.slice(1).split('-').map(Number):[];return modules.filter(m=>f==='all'||(ids?ids.includes(m.id):m.lessons.some(l=>l>=a&&l<=b))).flatMap(m=>m.q.concat(XQ[m.id]||[]).map(q=>({q,m})))}
function quiz(){main.innerHTML=`<div class="quiz-page">${backHome}<header class="page-header"><p class="eyebrow">Examen · entraînement</p><h1>Quiz mélangé</h1><p id="quiz-intro">${quizIntro('all')}</p></header><div class="lesson-body"><div class="quiz-tools"><label><span class="tools-label">Questions tirées de</span><select id="quiz-filter">${quizFilters.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label><button type="button" class="btn" id="quiz-new">Nouveau tirage</button></div><section class="practice quiz" id="quiz-box" aria-label="Quiz"></section></div></div>`;
 const f=$('#quiz-filter');f.onchange=()=>newQuiz(f.value);$('#quiz-new').onclick=()=>newQuiz(f.value);
 if(quizState&&quizFilters.some(([v])=>v===quizState.filter)){f.value=quizState.filter;drawQuiz()}else newQuiz('all',true)}
function newQuiz(filter,initial){quizState={filter,items:filter==='recits'?recitPool():shuffle(quizPool(filter)).slice(0,20),i:0,res:[]};drawQuiz(!initial)}
// The story so far: earlier items of the same récit with their first answer filled in.
const filled=q=>{const a=esc(q[1].split('|')[0]);return q[0].includes('___')?esc(q[0]).replace(/___(\s*\([^)]*\))?/,`<b>${a}</b>`):esc(q[0])+' <b>'+a+'</b>'};
// Only the last sentence stays visible; the intro and earlier sentences open on demand, so the blank stays near the top on phones.
function recitHead(it){const prev=it.r.items.slice(0,it.k),early=prev.slice(0,-1),intro=it.r.intro?`<p class="recit-intro">${it.r.intro}</p>`:'';
 const more=intro||early.length?`<details class="recit-earlier"><summary>${early.length?`Relire le début (${early.length} phrase${early.length>1?'s':''})`:'Relire l’introduction'}</summary><div>${intro}${early.length?`<p class="recit-sofar">${early.map(filled).join(' ')}</p>`:''}</div></details>`:'';
 return `<div class="recit-head"><p class="eyebrow">Récit ${it.ri+1} sur ${RC.length} · phrase ${it.k+1} sur ${it.r.items.length}</p><h3>${it.r.title}</h3>${it.k?more+`<p class="recit-sofar recit-last">${early.length?'… ':''}${filled(prev[prev.length-1])}</p>`:intro}</div>`}
// Bring the card (up to its answer buttons) into view after a question loads; focus stays off the input so no keyboard pops up.
function scrollCard(box){const top=box.getBoundingClientRect().top,end=box.querySelector('.question .answer-row,.question .choices'),bottom=end?end.getBoundingClientRect().bottom:0,bar=innerWidth<=760?57:0;if(top<bar||bottom>innerHeight-8)box.scrollIntoView({block:'start',behavior:reducedMotion()?'auto':'smooth'})}
function drawQuiz(focus){const s=quizState,n=s.items.length,box=$('#quiz-box'),score=s.res.filter(Boolean).length;$('#quiz-intro').textContent=quizIntro(s.filter);main.querySelector('.quiz-page').classList.toggle('running',s.i>0&&s.i<n);
 if(s.i>=n){const wrong=[];s.items.forEach((it,k)=>{if(!s.res[k]){const w=wrong.find(x=>x.m===it.m&&x.r===!!it.r);if(w)w.c++;else wrong.push({m:it.m,c:1,r:!!it.r})}});
  box.innerHTML=`<h2 id="quiz-head" tabindex="-1">Résultat : ${score} / ${n}</h2><p>${score===n?'Tout juste. Bravo !':score>=n*.6?'Bien. Revois les fiches ci-dessous, puis refais un tirage.':'Reprends les fiches ci-dessous avant le prochain tirage.'}</p>${wrong.length?`<h3>Fiches à revoir</h3><ul class="review-list">${wrong.sort((a,b)=>a.m.n.localeCompare(b.m.n)).map(({m,c,r})=>`<li><a href="#${m.id}${r?'/recits':''}">Fiche ${m.n} · ${m.title}${r?' · récits':''}</a> <small>${c} erreur${c>1?'s':''}</small></li>`).join('')}</ul>`:''}<div class="answer-row quiz-nav"><button type="button" class="btn primary ready" id="quiz-again">Nouveau tirage</button></div>`;
  $('#quiz-again').onclick=()=>newQuiz(s.filter)}
 else{const {q,m}=s.items[s.i];box.innerHTML=`<div class="quiz-progress"><span id="quiz-head" tabindex="-1">Question ${s.i+1} sur ${n}</span><span>${score} bonne${score>1?'s':''} réponse${score>1?'s':''}</span></div><div class="progress-bar" aria-hidden="true"><span style="width:${s.i/n*100}%"></span></div><a class="source-tag" href="#${m.id}${s.items[s.i].r?'/recits':''}">Fiche ${m.n} · ${m.title}</a>${s.items[s.i].r?recitHead(s.items[s.i]):''}${questionHTML(q,0,s.i+1)}<div class="answer-row quiz-nav"><button type="button" class="btn primary" id="quiz-next">${s.i+1<n?'Question suivante →':'Voir le résultat'}</button></div>`;
  // Only the first check or reveal counts towards the score; retrying is still allowed.
  bindQuestions(box,[q],(_,ok)=>{if(s.res[s.i]===undefined)s.res[s.i]=ok;$('#quiz-next').classList.add('ready')});
  $('#quiz-next').onclick=()=>{if(s.res[s.i]===undefined)s.res[s.i]=false;s.i++;drawQuiz(true)}}
 if(focus){$('#quiz-head').focus({preventScroll:true});scrollCard(box)}}

function route(){if(location.hash==='#generations'){location.replace('#oral/generations');return}const parts=location.hash.slice(1).split('/'),id=parts[0]||'accueil',sub=parts[1]?decodeURIComponent(parts[1]):null;stopTimers();closeMenu();closeSearch();document.querySelectorAll('#nav a').forEach(a=>{const active=a.dataset.page===id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const m=modules.find(x=>x.id===id);setTitle(m?m.title:pageTitles[id]||'Révisions B1−');if(m)modulePage(m);else if(id==='verbes')verbPage(sub);else if(id==='test')exam();else if(id==='oral')oral(sub);else if(id==='ecrire')ecrire();else if(id==='lire')lire(sub);else if(id==='quiz')quiz();else home();window.scrollTo(0,0);if(id==='oral'&&sub&&$('#topic-title'))$('#oral-practice').scrollIntoView();if(m&&sub){const el=document.getElementById(sub);if(el){const go=()=>el.scrollIntoView({behavior:'instant'});go();if(document.fonts)document.fonts.ready.then(()=>requestAnimationFrame(go))}}}
$('#search').oninput=e=>{const q=searchNorm(e.target.value);const r=$('#results');if(!q){r.hidden=true;return}const matches=modules.filter(m=>searchNorm(m.title+' '+m.subtitle+' '+m.sections.map(s=>s.join(' ')).join(' ')).includes(q));const vv=verbs.filter(v=>searchNorm(v.join(' ')).includes(q)),vHit=v=>searchNorm(v[0]).startsWith(q),vLink=v=>`<a href="#verbes/${encodeURIComponent(v[0])}">${v[0]}<small>Conjugaison · participe ${v[2]}</small></a>`;const pages=examPages.filter(p=>searchNorm(p.join(' ')).includes(q)),topics=OT.filter(t=>searchNorm(strip([t.title,t.document,...t.vocab.flat()].join(' '))).includes(q)),texts=LX.filter(t=>searchNorm(strip(t.title)).includes(q)),recitHit=RC.length&&searchNorm(strip('récits à compléter récit histoire passé '+RC.map(r=>r.title+' '+r.intro).join(' '))).includes(q);
 r.innerHTML=(recitHit?`<a href="#choisir/recits">Récits à compléter<small>Fiche Choisir le bon passé · ${RC.length} histoires</small></a>`:'')+pages.map(([id,t,sub])=>`<a href="#${id}">${t}<small>Examen · ${sub}</small></a>`).join('')+vv.filter(vHit).slice(0,3).map(vLink).join('')+matches.slice(0,6).map(m=>`<a href="#${m.id}">${m.title}<small>${m.subtitle}</small></a>`).join('')+texts.slice(0,4).map(t=>`<a href="#lire/${encodeURIComponent(t.id)}">${t.title}<small>Texte de lecture · ${typeLabel(t.type).toLowerCase()}</small></a>`).join('')+topics.slice(0,4).map(t=>`<a href="#oral/${encodeURIComponent(t.id)}">${t.title}<small>Sujet d’oral</small></a>`).join('')+vv.filter(v=>!vHit(v)).slice(0,5).map(vLink).join('');if(!r.innerHTML)r.innerHTML='<p>Aucun résultat. Essaie « passé », « depuis » ou « prendre ».</p>';r.hidden=false};
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#results').hidden=true;if(e.target.closest('#results a'))closeSearch()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if(document.body.classList.contains('search-open'))closeSearch(true);else $('#results').hidden=true}});window.addEventListener('hashchange',route);route();
$('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};

function conditional(v,future=false){const stems={'aller':'ir','s’appeler':'appeller','avoir':'aur','courir':'courr','devoir':'devr','être':'ser','faire':'fer','pouvoir':'pourr','recevoir':'recevr','savoir':'saur','venir':'viendr','voir':'verr','vouloir':'voudr'};const inf=v[0];const stem=stems[inf]||inf.replace(/e$/,'');return (future?['ai','as','a','ons','ez','ont']:['ais','ais','ait','ions','iez','aient']).map((e,i)=>(inf==='s’appeler'?['m’','t’','s’','nous ','vous ','s’'][i]:'')+stem+e);}
function subjunctive(v){
 const special={'être':'sois,sois,soit,soyons,soyez,soient','avoir':'aie,aies,ait,ayons,ayez,aient','aller':'aille,ailles,aille,allions,alliez,aillent','faire':'fasse,fasses,fasse,fassions,fassiez,fassent','pouvoir':'puisse,puisses,puisse,puissions,puissiez,puissent','savoir':'sache,saches,sache,sachions,sachiez,sachent','vouloir':'veuille,veuilles,veuille,voulions,vouliez,veuillent'};
 if(special[v[0]])return special[v[0]].split(',');
 const p=v[1].split(',');const reflex=v[0]==='s’appeler';const a=reflex?'appell':p[5].slice(0,-3);const b=reflex?'appel':v[0]==='manger'?'mang':p[3].slice(0,-3);
 return ['e','es','e','ions','iez','ent'].map((e,i)=>(reflex?['m’','t’','s’','nous ','vous ','s’'][i]:'')+(i===3||i===4?b:a)+e);
}
